svg.script:
(function(){
const svg=document.currentScript.ownerSVGElement;
// Select a saved public example with ?chart=camille (or ?person=camille).
// The SVG can also be embedded elsewhere; in that case the parent URL applies.
function applyChartParameter(){
 const params=new URLSearchParams(location.search),parentParams=(()=>{try{return new URLSearchParams(parent.location.search);}catch{return new URLSearchParams();}})();
 const requested=(params.get('chart')||params.get('person')||parentParams.get('chart')||parentParams.get('person')||'').trim().toLowerCase();
 if(!requested)return;
 const examples={
  camille:[4,5,7,9,10,11,12,15,21,25,26,28,29,34,35,45,46,50,64],
  daniel:[1,2,3,7,8,10,12,13,16,19,31,34,36,41,43,46,48,51,56,57,58,60],
  aleia:[1,2,4,6,7,8,13,16,22,23,25,31,36,41,42,45,53],
  finn:[3,19,23,24,25,27,32,33,36,37,38,41,44,51,57,60,61,63]
 };
 const gates=examples[requested];
  if(!gates){svg.setAttribute('aria-label',`Human Design BodyGraph template. Unknown chart: ${requested}.`);return;}
 const active=new Set(gates);
 svg.querySelectorAll('.gate').forEach(gate=>{
  const on=active.has(Number(gate.dataset.gate));
  gate.dataset.state=on?'closed':'open';
  if(requested==='daniel'){
   if(on)gate.dataset.state='closed';
   else{gate.dataset.state='open';gate.removeAttribute('data-activation');gate.removeAttribute('data-line-activation');gate.removeAttribute('data-line-name');gate.removeAttribute('data-line-reading');}
   return;
  }
  gate.removeAttribute('data-activation');
  gate.removeAttribute('data-line-activation');
  gate.removeAttribute('data-line-name');
  gate.removeAttribute('data-line-reading');
  if(on)gate.setAttribute('data-activation','chart');
  const base=(gate.dataset.reading||gate.getAttribute('aria-label')||'').split(/(?: Activated in your natal chart| Unactivated in this chart| Unactivated in your chart)/)[0];
  gate.setAttribute('aria-label',`${base}${on?' Activated in the '+requested+' example chart.':' Unactivated in the '+requested+' example chart.'}`);
 });
 svg.querySelectorAll('.channel-group').forEach(channel=>{
  const defined=active.has(Number(channel.dataset.from))&&active.has(Number(channel.dataset.to));
  channel.dataset.defined=String(defined);
  channel.setAttribute('aria-label',defined?'Defined channel in this chart.':'Incomplete channel in this chart.');
 });
 svg.querySelectorAll('.center').forEach(center=>{
  const connected=Array.from(svg.querySelectorAll('.channel-group')).some(channel=>channel.dataset.defined==='true'&&(svg.getElementById('gate-'+channel.dataset.from)?.dataset.center===center.dataset.center||svg.getElementById('gate-'+channel.dataset.to)?.dataset.center===center.dataset.center));
  center.dataset.defined=String(connected);
  center.setAttribute('aria-label',`${center.dataset.center} center — ${connected?'Defined':'Undefined'} in the ${requested} example chart.`);
 });
 svg.setAttribute('aria-label',`Human Design BodyGraph for ${requested}`);
  const displayName=requested==='finn'?'Finn':requested==='aleia'?'Aleia':requested[0].toUpperCase()+requested.slice(1);
  svg.querySelector('#title')?.replaceChildren(document.createTextNode(`Human Design BodyGraph · ${displayName}`));
 svg.querySelector('#desc')?.replaceChildren(document.createTextNode(`Interactive Human Design BodyGraph for the public ${requested} example chart.`));
}
const interactive='.gate, .channel-group, .center';
const flowControl=svg.getElementById('flow-control'),gateDemoControl=svg.getElementById('gate-demo-control');
const tooltip=svg.getElementById('svg-tooltip');
const lasso=svg.getElementById('selection-lasso');let lassoItem=null;
function updateLasso(item=lassoItem){lassoItem=item;if(!lasso||!item){if(lasso)lasso.style.display='none';return;}const target=item.matches('.gate')?item.querySelector('.gate-marker'):item.matches('.center')?item.querySelector('.center-shape'):item,rect=target?.getBoundingClientRect(),matrix=svg.getScreenCTM();if(!rect||!matrix||!rect.width&&!rect.height){lasso.style.display='none';return;}const pad=item.matches('.gate')?7:8,inverse=matrix.inverse(),corners=[[rect.left-pad,rect.top-pad],[rect.right+pad,rect.top-pad],[rect.right+pad,rect.bottom+pad],[rect.left-pad,rect.bottom+pad]].map(([x,y])=>{const point=svg.createSVGPoint();point.x=x;point.y=y;return point.matrixTransform(inverse);}),xs=corners.map(point=>point.x),ys=corners.map(point=>point.y),left=Math.min(...xs),right=Math.max(...xs),top=Math.min(...ys),bottom=Math.max(...ys);lasso.setAttribute('cx',((left+right)/2).toFixed(3));lasso.setAttribute('cy',((top+bottom)/2).toFixed(3));lasso.setAttribute('rx',Math.max(1,(right-left)/2).toFixed(3));lasso.setAttribute('ry',Math.max(1,(bottom-top)/2).toFixed(3));lasso.style.display='';}
const tooltipRect=tooltip.querySelector('rect');
const tooltipText=tooltip.querySelector('text');
const embedded=window.parent!==window;if(embedded)tooltip.style.display='none';
let tooltipItem=null,lastPointerType='';function hideTooltip(){tooltip.classList.remove('is-visible');tooltip.setAttribute('aria-hidden','true');if(embedded)window.parent.postMessage({type:'bodygraph-info',action:'hide'},'*');tooltipItem=null;}tooltip.addEventListener('pointerdown',event=>event.stopPropagation());tooltip.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();clear();hideTooltip();});tooltip.addEventListener('pointerout',event=>{if(!tooltip.contains(event.relatedTarget)&&!fromTarget(event.relatedTarget)){clear();hideTooltip();}});
function gateName(gate){if(!gate)return'Gate';const name=gate.dataset.gateName||(gate.getAttribute('aria-label')||'').split(':')[0].trim()||'Gate',line=gate.dataset.lineActivation?.split('|')[1],lineName=gate.dataset.lineName;return line&&lineName?`${name} (${line} · ${lineName})`:name;}
function gateLabel(gate){if(!gate)return'Gate';return`Gate ${gate.dataset.gate} — ${gateName(gate)}`;}
function gateLineReading(gate){const activation=gate?.dataset.lineActivation;if(!activation)return'';const[side,gateLine]=activation.split('|'),name=gate.dataset.lineName,reading=gate.dataset.lineReading;return name&&reading?`${side}: ${gateLine}, ${name}. ${reading}`:'';}
function gateReading(gate){return gate?.dataset.reading||((gate?.getAttribute('aria-label')||'').split(':').slice(1).join(':').split(/\s+(?:Activated|Unactivated) in your natal chart|\s+Unactivated in this chart/)[0].trim());}
function activationSide(gate){const activation=gate?.dataset.activation||'',sides=[];if(/design/i.test(activation))sides.push('Design');if(/personality/i.test(activation))sides.push('Personality');return sides.length?sides.join(' and '):'no natal Design or Personality activation';}
function planetaryMirrorPairs(gate){if(!gate?.matches('.gate'))return[];const activations=new Map();svg.querySelectorAll('.gate[data-activation]').forEach(candidate=>{(candidate.dataset.activation||'').split(',').forEach(value=>{const match=value.trim().match(/^(design|personality)\s+(.+)$/i);if(!match)return;const side=match[1].toLowerCase(),planet=match[2].trim(),key=planet.toLowerCase();if(!activations.has(key))activations.set(key,{planet});activations.get(key)[side]=candidate;});});const pairs=[];activations.forEach(({planet,design,personality})=>{if(!design||!personality||design!==gate&&personality!==gate)return;pairs.push({planet,design:{gate:design.dataset.gate,name:gateName(design)},personality:{gate:personality.dataset.gate,name:gateName(personality)}});});return pairs;}
function planetaryMirrorReading(pairs){return pairs.map(pair=>` Personality ${pair.planet}: Gate ${pair.personality.gate} — ${pair.personality.name}; Design: Gate ${pair.design.gate} — ${pair.design.name}.`).join('');}
function channelReading(channel){const explicit=channel?.dataset.reading;if(explicit)return explicit;return(channel?.getAttribute('aria-label')||'').replace(/^(?:Channel of [^,.]+, defined\.|Incomplete channel\.|Open channel\.)\s*/i,'').trim();}
function counterpartReading(item){if(item.matches('.channel-group'))return'';const channel=svg.querySelector(`.channel-group[data-from="${item.dataset.gate}"]`)||svg.querySelector(`.channel-group[data-to="${item.dataset.gate}"]`);if(!channel)return'';const from=svg.getElementById('gate-'+channel.dataset.from),to=svg.getElementById('gate-'+channel.dataset.to),other=item===from?to:from,channelId=channel.dataset.channel||`${channel.dataset.from}-${channel.dataset.to}`,channelName=(channel.dataset.reading||'').split(':',1)[0].trim()||((channel.getAttribute('aria-label')||'').match(/^Channel of ([^,]+)/i)?.[1]||'');return` Its partner is ${gateLabel(other)}; together they form ${channelName?`the ${channelName} Channel (${channelId})`:`Channel ${channelId}`}.`;}
function gateStatus(gate){const activation=gate?.dataset.activation;if(activation)return`Active in this chart through ${activation.split(',').map(value=>value.trim()).join(' and ')}.`;if(gate?.hasAttribute('data-transit-planets'))return`Not activated natally; currently highlighted by ${gate.dataset.transitPlanets}.`;if(gate?.hasAttribute('data-demo-active'))return'Highlighted in the current demonstration.';return'No natal activation here; in Human Design this gate is open to influence from people and transits.';}
function channelStatus(channel){const endpoints=[svg.getElementById('gate-'+channel.dataset.from),svg.getElementById('gate-'+channel.dataset.to)],active=endpoints.filter(gate=>gate?.hasAttribute('data-activation'));if(active.length===1){const hanging=active[0],missing=endpoints.find(gate=>gate!==hanging);return`One end is active through ${activationSide(hanging)} at Gate ${hanging.dataset.gate}; the open end is Gate ${missing?.dataset.gate}.`;}if(active.length===2)return'Both gates are active in this chart, so the channel is defined.';return'Neither gate has a natal activation here, so the channel is open to conditioning from people and transits.';}
function showTooltip(item,event){
 const copy=window.CastaliaBodyGraphCopy;let detail=item.getAttribute('data-tooltip')||item.getAttribute('aria-label')||'';if(item.matches('.gate'))detail=copy?.gates?.[item.dataset.gate]||gateReading(item)||detail;if(item.matches('.gate'))detail+=` ${gateLineReading(item)} ${gateStatus(item)}`;if(item.matches('.channel-group'))detail=`${copy?.channels?.[item.dataset.channel]||channelReading(item)||detail} ${channelStatus(item)}`;if(item.matches('.center')){const centerId=item.dataset.center||item.id.replace(/^center-/,'');const gates=Array.from(svg.querySelectorAll('.gate')).filter(gate=>gate.dataset.center===centerId&&gate.hasAttribute('data-activation')),designGates=gates.filter(gate=>/design/i.test(gate.dataset.activation||'')).map(gateLabel),personalityGates=gates.filter(gate=>/personality/i.test(gate.dataset.activation||'')).map(gateLabel),natalDefined=item.dataset.defined==='true',state=natalDefined?'Defined in this chart, so this theme tends to be more consistent.':gates.length?'Some gates are active, but no full channel defines this center; its expression may vary more with context.':'Open in this chart, so you may amplify or take in this theme from people and places around you.',label=item.getAttribute('aria-label')?.split(' center')[0]||centerId;detail=`${copy?.centers?.[centerId]||'This center describes a recurring part of how you experience and respond to life.'} ${state}`;if(designGates.length)detail+=` Design (body/unconscious): ${designGates.join('; ')}.`;if(personalityGates.length)detail+=` Personality (conscious): ${personalityGates.join('; ')}.`;}if(item.matches('.gate'))detail+=counterpartReading(item);if(!detail)return;
 if(item.matches('.gate[data-transit-planets]'))detail+=` Current transit activation: ${item.dataset.transitPlanets}.`;
 if(item.matches('.channel-group')){const circuitLabel=(item.dataset.circuitLabel||item.dataset.circuit||'Unclassified').replace(/\s+(?:Circuit|channel group)$/i,'');const groupLabel=(item.dataset.circuitGroupLabel||'').replace(/\s+circuit group$/i,'');detail+=` ${circuitLabel} circuit${groupLabel?` · ${groupLabel}`:''}.`;}if(item.matches('.channel-group[data-transit-channel]'))detail+=' Both gates are activated by the current transits.';
 const fromGate=item.matches('.channel-group')?svg.getElementById('gate-'+item.dataset.from):null,toGate=item.matches('.channel-group')?svg.getElementById('gate-'+item.dataset.to):null,reference=item.matches('.gate')?gateLabel(item):item.matches('.center')?`${(item.dataset.center||item.id.replace(/^center-/,'')).replace(/^./,letter=>letter.toUpperCase())} center`: `Channel ${item.dataset.channel} · ${gateLabel(fromGate)} → ${gateLabel(toGate)}`;
 const planetPairs=item.matches('.gate')?planetaryMirrorPairs(item):[];if(!embedded)detail+=planetaryMirrorReading(planetPairs);
 if(embedded)window.parent.postMessage({type:'bodygraph-info',action:'show',title:reference,detail,planetPairs},'*');
 const words=(reference+' '+detail).split(/\s+/),lines=[];let line='';
 words.forEach(word=>{const candidate=line?line+' '+word:word;if(candidate.length>42&&line){lines.push(line);line=word;}else line=candidate;});if(line)lines.push(line);
 const viewBox=svg.viewBox.baseVal;
 while(tooltipText.firstChild)tooltipText.removeChild(tooltipText.firstChild);
 const width=Math.max(40,Math.min(190,viewBox.width-16)),maxLines=Math.max(5,Math.floor((Math.min(88,viewBox.height*.22)-12)/6));if(lines.length>maxLines){lines.length=maxLines;lines[maxLines-1]=lines[maxLines-1].replace(/[.…]*$/,'')+'…';}
 lines.forEach((value,index)=>{const span=document.createElementNS('http://www.w3.org/2000/svg','tspan');span.setAttribute('x','0');span.setAttribute('dy',index?'6':'0');span.textContent=value;tooltipText.appendChild(span);});
 const height=12+lines.length*6;tooltipRect.setAttribute('width',width);tooltipRect.setAttribute('height',height);tooltipText.setAttribute('font-size','5');tooltipText.setAttribute('transform','translate(6 8)');
 const margin=6,x=viewBox.x+(viewBox.width-width)/2,y=viewBox.y+viewBox.height-height-margin;
 tooltip.setAttribute('transform',`translate(${x} ${y})`);tooltip.classList.add('is-visible');tooltip.setAttribute('aria-hidden','false');tooltipItem=item;
}
let showAllFlow=true;
function positionGatesOnCenterBorders(){
 svg.querySelectorAll('.gate-marker').forEach(marker=>{marker.setAttribute('r','.5');marker.setAttribute('vector-effect','non-scaling-stroke');});
 const rootPoint=(element,x,y)=>{const point=svg.createSVGPoint();point.x=x;point.y=y;return point.matrixTransform(element.getCTM());};
 const polygonFor=shape=>{
  const points=[];
  if(shape.points){for(let i=0;i<shape.points.numberOfItems;i++){const point=shape.points.getItem(i);points.push(rootPoint(shape,point.x,point.y));}}
  else if(shape.localName==='path'&&shape.getTotalLength){const length=shape.getTotalLength(),steps=Math.max(96,Math.ceil(length*2));for(let i=0;i<steps;i++){const point=shape.getPointAtLength(length*i/steps);points.push(rootPoint(shape,point.x,point.y));}}
  else{const x=Number(shape.getAttribute('x')),y=Number(shape.getAttribute('y')),w=Number(shape.getAttribute('width')),h=Number(shape.getAttribute('height'));[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].forEach(([px,py])=>points.push(rootPoint(shape,px,py)));}
  return points;
 };
 const centers=new Map();svg.querySelectorAll('.center').forEach(center=>{const shape=center.querySelector('.center-shape');if(shape)centers.set(center.dataset.center,polygonFor(shape));});
 const nearestEdge=(point,vertices)=>{let best=null;for(let i=0;i<vertices.length;i++){const a=vertices[i],b=vertices[(i+1)%vertices.length],dx=b.x-a.x,dy=b.y-a.y,len2=dx*dx+dy*dy||1,t=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.y-a.y)*dy)/len2)),projected={x:a.x+t*dx,y:a.y+t*dy},distance=Math.hypot(point.x-projected.x,point.y-projected.y);if(!best||distance<best.distance)best={edge:i,t,distance};}return best;};
 const referenceEdges={head:{64:[1,0],61:[1,1],63:[1,2]},ajna:{47:[0,0],24:[0,1],4:[0,2],17:[2,0],11:[1,0],43:[1,1,1]},throat:{62:[0,0],23:[0,1],56:[0,2],35:[1,0],12:[1,1],45:[2,0],33:[2,1],8:[2,2],31:[2,3],20:[3,0],16:[3,1]},g:{13:[0,0],25:[0,1],46:[1,0,.72],15:[2,0,.28],10:[3,0],7:[3,1]},ego:{21:[0,0,.72],40:[1,0,.28],26:[2,0],51:[2,1]},solar:{36:[0,0,0.12],30:[1,0],55:[1,1],49:[1,2],6:[2,0],37:[2,1],22:[2,2]},sacral:{5:[0,0],14:[0,1],29:[0,2],59:[1,0],9:[2,0],3:[2,1],42:[2,2],27:[3,0],34:[3,1]},root:{53:[0,0],60:[0,1],52:[0,2],19:[1,0],39:[1,1],41:[1,2],58:[3,0],38:[3,1],54:[3,2]}};
 const buckets=new Map();svg.querySelectorAll('.gate').forEach(gate=>{const vertices=centers.get(gate.dataset.center),marker=gate.querySelector('.gate-marker');if(!vertices||!marker)return;const point=rootPoint(marker,Number(marker.getAttribute('cx')),Number(marker.getAttribute('cy'))),assignment=referenceEdges[gate.dataset.center]?.[gate.dataset.gate];let nearest;if(assignment){nearest={edge:assignment[0],t:assignment[2]??0.5,order:assignment[1]};}else if(gate.dataset.center==='ego'){const own=vertices.reduce((sum,p)=>({x:sum.x+p.x/vertices.length,y:sum.y+p.y/vertices.length}),{x:0,y:0}),dirs=[];svg.querySelectorAll('.channel-group').forEach(channel=>{const from=channel.dataset.from,to=channel.dataset.to;if(from!==gate.dataset.gate&&to!==gate.dataset.gate)return;const partner=svg.getElementById('gate-'+(from===gate.dataset.gate?to:from)),partnerCenter=partner&&centers.get(partner.dataset.center);if(partnerCenter){const target=partnerCenter.reduce((sum,p)=>({x:sum.x+p.x/partnerCenter.length,y:sum.y+p.y/partnerCenter.length}),{x:0,y:0}),dx=target.x-own.x,dy=target.y-own.y,len=Math.hypot(dx,dy)||1;dirs.push({x:dx/len,y:dy/len});}});if(dirs.length){const direction=dirs.reduce((sum,d)=>({x:sum.x+d.x/dirs.length,y:sum.y+d.y/dirs.length}),{x:0,y:0}),len=Math.hypot(direction.x,direction.y)||1,dx=direction.x/len,dy=direction.y/len;let hit=null;for(let edge=0;edge<vertices.length;edge++){const a=vertices[edge],b=vertices[(edge+1)%vertices.length],ex=b.x-a.x,ey=b.y-a.y,den=dx*ey-dy*ex;if(Math.abs(den)<1e-8)continue;const rx=a.x-own.x,ry=a.y-own.y,t=(rx*ey-ry*ex)/den,u=(rx*dy-ry*dx)/den;if(t>=0&&u>=0&&u<=1&&(!hit||t<hit.t))hit={edge,t,u};}nearest=hit?{edge:hit.edge,t:hit.u}:nearestEdge(point,vertices);}else nearest=nearestEdge(point,vertices);}else nearest=nearestEdge(point,vertices);const key=`${gate.dataset.center}:${nearest.edge}`;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push({gate,vertices,...nearest});});
 const placements=new Map(),place=(gate,vertices,edge,desired)=>{const inverse=gate.getCTM().inverse(),local=svg.createSVGPoint();local.x=desired.x;local.y=desired.y;const target=local.matrixTransform(inverse);gate.querySelectorAll('.gate-hit,.gate-marker,.gate-contrast-ring,.gate-number').forEach(node=>{node.setAttribute('cx',target.x.toFixed(3));node.setAttribute('cy',target.y.toFixed(3));});placements.set(gate.dataset.gate,{vertices,edge,desired});};
 buckets.forEach(items=>{items.sort((a,b)=>(a.order??a.t)-(b.order??b.t));const a=items[0].vertices[items[0].edge],b=items[0].vertices[(items[0].edge+1)%items[0].vertices.length];items.forEach((item,index)=>{const t=items.length===1?item.t:items.length===2?(index+1)/3:.12+.76*(index/(items.length-1)),desired={x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};place(item.gate,item.vertices,item.edge,desired);});});
 const gVertices=centers.get('g'),gate1=svg.getElementById('gate-1'),gate2=svg.getElementById('gate-2');if(gVertices&&gate1)place(gate1,gVertices,0,gVertices[0]);if(gVertices&&gate2)place(gate2,gVertices,2,gVertices[2]);
 const solarVertices=centers.get('solar'),solarAnchors={36:[2,.9],22:[2,.7],37:[2,.48],6:[2,.12],49:[1,.88],55:[1,.5],30:[1,.12]};if(solarVertices)Object.entries(solarAnchors).forEach(([id,[edge,t]])=>{const a=solarVertices[edge],b=solarVertices[(edge+1)%solarVertices.length],desired={x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t},gate=svg.getElementById('gate-'+id);if(gate)place(gate,solarVertices,edge,desired);});
 const ajnaVertices=centers.get('ajna'),gate43=svg.getElementById('gate-43');if(ajnaVertices&&gate43)place(gate43,ajnaVertices,1,ajnaVertices[2]);
 const spleenShape=svg.getElementById('center-spleen')?.querySelector('.center-shape'),spleenVertices=centers.get('spleen'),spleenAnchors={48:[127,240],57:[135,245],44:[145,251],50:[159,259],32:[148,266],28:[137,273],18:[127,279]};if(spleenShape&&spleenVertices){Object.entries(spleenAnchors).forEach(([id,[x,y]])=>{const gate=svg.getElementById('gate-'+id);if(!gate)return;const target=rootPoint(spleenShape,x,y),nearest=nearestEdge(target,spleenVertices),a=spleenVertices[nearest.edge],b=spleenVertices[(nearest.edge+1)%spleenVertices.length],projected={x:a.x+(b.x-a.x)*nearest.t,y:a.y+(b.y-a.y)*nearest.t};place(gate,spleenVertices,nearest.edge,projected);});}
 const parent=new Map(),find=id=>{if(!parent.has(id))parent.set(id,id);if(parent.get(id)!==id)parent.set(id,find(parent.get(id)));return parent.get(id);},join=(a,b)=>{const ra=find(a),rb=find(b);if(ra!==rb)parent.set(ra,rb);};
 svg.querySelectorAll('.channel-group').forEach(channel=>{const d=channel.querySelector('.channel')?.getAttribute('d')||'',m=d.match(/^M\s*(-?[\d.]+),(-?[\d.]+)\s*C\s*(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)$/);if(!m)return;const xs=[Number(m[1]),Number(m[3]),Number(m[5]),Number(m[7])];if(Math.max(...xs)-Math.min(...xs)<=8)join(channel.dataset.from,channel.dataset.to);});
 const components=new Map();parent.forEach((_,id)=>{const root=find(id);if(!components.has(root))components.set(root,[]);components.get(root).push(id);});
