svg.addEventListener('pointerover',event=>{if(event.pointerType==='touch')return;const item=fromTarget(event.target);if(item){activate(item);showTooltip(item,event);}});
svg.addEventListener('pointerout',event=>{if(event.pointerType==='touch'||tooltip.contains(event.relatedTarget))return;const item=fromTarget(event.target);if(item&&!item.contains(event.relatedTarget)){const next=fromTarget(event.relatedTarget);if(next){activate(next);showTooltip(next,event);}else{clear();hideTooltip();}}});
svg.addEventListener('click',event=>{if(lastPointerType!=='touch')return;const item=fromTarget(event.target);if(!item)return;if(tooltipItem===item){clear();hideTooltip();}else{activate(item);showTooltip(item,event);}setTimeout(()=>{lastPointerType='';},0);});
svg.addEventListener('focusin',event=>{if(lastPointerType==='touch')return;const item=fromTarget(event.target);if(item){activate(item);showTooltip(item,event);}});
svg.addEventListener('focusout',event=>{if(lastPointerType==='touch')return;if(!fromTarget(event.relatedTarget)){clear();hideTooltip();}else{const next=fromTarget(event.relatedTarget);activate(next);showTooltip(next,event);}});
})();
